import {reportData,volumeBuckets,taskLeaves,stamp,SEATTLE} from './analytics.js?v=0.7.1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>v===null||!Number.isFinite(v)?'Not recorded':Number(v.toFixed(1)).toLocaleString();
const date=v=>new Date(v).toLocaleDateString('en-US',{timeZone:SEATTLE,month:'short',day:'numeric'});
const time=v=>stamp(v)===null?'Not recorded':new Date(v).toLocaleTimeString('en-US',{timeZone:SEATTLE,hour:'numeric',minute:'2-digit'});
const GREEN='#275947',GOLD='#bf8b44',BLUE='#5c8192',PALE='#93a981';
const series=[{key:'single',label:'Single',color:GREEN},{key:'batch',label:'Batch',color:GOLD}];
function table(headers,rows){return `<details class="chart-data"><summary>View chart data</summary><div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;}
function legend(items){return `<div class="chart-legend">${items.map(s=>`<span><i style="background:${s.color}"></i>${esc(s.label)}</span>`).join('')}</div>`;}
function empty(message='Not recorded for these shifts yet.'){return `<div class="chart-empty">${esc(message)}</div>`;}
function card(title,subtitle,body,wide=false){return `<section class="card chart-card ${wide?'chart-wide':''}"><h3>${esc(title)}</h3><p class="chart-caption">${esc(subtitle)}</p>${body}<p class="chart-readout" role="status" aria-live="polite"></p></section>`;}
function svgStart(label,height=248){return `<svg class="report-svg" viewBox="0 0 600 ${height}" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title>`;}
function note(text){return `data-chart-note="${esc(text)}" tabindex="0" role="button" aria-label="${esc(text)}"`;}
function niceAxis(value){const v=Math.max(1,value),raw=v/4,power=10**Math.floor(Math.log10(raw)),step=v<=4&&Number.isInteger(v)?1:[1,2,2.5,5,10].find(n=>n*power>=raw)*power,max=Math.ceil(v/step)*step;return {max,ticks:Array.from({length:Math.round(max/step)+1},(_,i)=>i*step)};}
function bars(title,items,sets=series,format=v=>num(v),signed=false,grouped=false){
 if(!items.length)return empty('No matching records.');
 const all=items.flatMap(i=>sets.map(s=>i[s.key])).filter(Number.isFinite);if(!all.length)return empty();
 const axis=niceAxis(Math.max(1,...(grouped?all:items.map(i=>sets.reduce((n,s)=>n+Math.abs(i[s.key]??0),0))))),max=axis.max,left=42,right=584,top=20,bottom=199,zero=signed?107:bottom,scale=(signed?82:bottom-top)/max,step=(right-left)/items.length,width=Math.min(34,step*.68/(grouped?sets.length:1));
 let svg=svgStart(title);for(const value of axis.ticks){const y=zero-value*scale;svg+=`<line x1="${left}" x2="${right}" y1="${y}" y2="${y}" class="chart-gridline"/><text x="34" y="${y+4}" text-anchor="end" class="chart-axis">${num(value)}</text>`;}
 if(signed)for(const v of axis.ticks.slice(1)){const y=zero+v*scale;svg+=`<line x1="${left}" x2="${right}" y1="${y}" y2="${y}" class="chart-gridline"/><text x="34" y="${y+4}" text-anchor="end" class="chart-axis">−${num(v)}</text>`;}
 if(signed)svg+=`<line x1="${left}" x2="${right}" y1="${zero}" y2="${zero}" class="chart-zero"/>`;
 items.forEach((item,i)=>{let offset=0;const x=left+step*(i+.5)-width/2;for(const [si,s] of sets.entries()){const v=item[s.key];if(!Number.isFinite(v))continue;const h=Math.abs(v)*scale,y=signed?(v<0?zero:zero-h):bottom-(grouped?0:offset)-h;const barX=grouped?x+(si-(sets.length-1)/2)*(width+4):x;const label=`${item.label}: ${s.label} ${format(v)}`;svg+=`<rect x="${barX}" y="${y}" width="${width}" height="${Math.max(h,.6)}" rx="3" fill="${signed?(v>0?GOLD:GREEN):s.color}" ${note(label)}><title>${esc(label)}</title></rect>`;if(!signed)offset+=h;}if(items.length<=12||i%Math.ceil(items.length/9)===0||i===items.length-1)svg+=`<text x="${x+width/2}" y="224" text-anchor="middle" class="chart-axis">${esc(item.short||item.label)}</text>`;});
 return svg+'</svg>'+legend(signed?[{label:'Early (below zero)',color:GREEN},{label:'Late (above zero)',color:GOLD}]:sets)+table(['Period',...sets.map(s=>s.label)],items.map(i=>[i.label,...sets.map(s=>Number.isFinite(i[s.key])?format(i[s.key]):'Not recorded')]));
}
function line(title,rows,key,label,color,unit){
 if(!rows.some(r=>Number.isFinite(r[key])))return empty();const values=rows.map(r=>r[key]).filter(Number.isFinite),axis=niceAxis(Math.max(1,...values)),max=axis.max,l=42,r=582,t=20,b=190,x=i=>l+(rows.length===1?(r-l)/2:i*(r-l)/(rows.length-1)),y=v=>b-v/max*(b-t);
 let svg=svgStart(title),path='';for(const v of axis.ticks){svg+=`<line x1="${l}" x2="${r}" y1="${y(v)}" y2="${y(v)}" class="chart-gridline"/><text x="34" y="${y(v)+4}" text-anchor="end" class="chart-axis">${num(v)}</text>`;}
 let started=false;rows.forEach((row,i)=>{if(!Number.isFinite(row[key])){started=false;return;}path+=`${started?'L':'M'}${x(i)},${y(row[key])} `;started=true;});svg+=`<path d="${path}" fill="none" stroke="${color}" stroke-width="2.5"/>`;
 rows.forEach((row,i)=>{if(Number.isFinite(row[key])){const text=`${date(row.startedAt)} · ${label}: ${num(row[key])} ${unit}`;svg+=`<circle cx="${x(i)}" cy="${y(row[key])}" r="4.5" fill="${color}" ${note(text)}><title>${esc(text)}</title></circle>`;}if(rows.length<=8||i%Math.ceil(rows.length/7)===0||i===rows.length-1)svg+=`<text x="${x(i)}" y="218" text-anchor="middle" class="chart-axis">${esc(date(row.startedAt))}</text>`;});
 return svg+'</svg>'+table(['Shift',`${label} (${unit})`],rows.map(s=>[`${date(s.startedAt)} ${time(s.startedAt)}`,num(s[key])]));
}
function donut(data){const single=data.runs.filter(r=>r.deliveryIds.length===1).length,batch=data.runs.filter(r=>r.deliveryIds.length>1).length,total=single+batch;if(!total)return empty('No classified delivery runs recorded.');const share=single/total*100;return `<div class="run-donut"><svg viewBox="0 0 200 200" role="img" aria-label="${single} single trips and ${batch} batch trips"><circle cx="100" cy="100" r="73" fill="none" stroke="${GOLD}" stroke-width="24"/><circle cx="100" cy="100" r="73" fill="none" stroke="${GREEN}" stroke-width="24" pathLength="100" stroke-dasharray="${share} ${100-share}" transform="rotate(-90 100 100)"/><text x="100" y="98" text-anchor="middle" class="donut-total">${total}</text><text x="100" y="121" text-anchor="middle" class="chart-axis">recorded trips</text></svg><div>${legend(series)}<p><strong>${single}</strong> single trips<br><strong>${batch}</strong> batch trips</p><p class="muted">${data.deliveries.length} completed deliveries · ${num(data.deliveries.length/total)} per recorded trip</p></div></div>`;}
function taskBars(data){const max=Math.max(1,...data.taskCounts.map(t=>t.count));if(!data.taskCounts.some(t=>t.count))return empty('No kitchen tasks checked off in these shifts. Older shifts may not have task records.');return `<div class="task-chart">${data.taskCounts.map(t=>`<button type="button" class="task-bar" ${note(`${t.label}: completed on ${t.count} of ${data.shifts.length} selected shifts`)}><span>${esc(t.label)}</span><div><i style="width:${t.count/max*100}%"></i></div><strong>${t.count}</strong></button>`).join('')}</div><p class="muted">${data.taskShiftCount} of ${data.shifts.length} shifts have task records. Counts are shifts with a recorded check-off, not quantities made. An unchecked task does not mean it was required.</p>`;}
function heatmap(data){if(!data.deliveries.length)return empty('No completed deliveries.');const max=Math.max(1,...data.heat.flatMap(r=>r.hours)),used=Array.from({length:24},(_,i)=>i).filter(h=>data.heat.some(d=>d.hours[h])),hours=used.length?Array.from({length:Math.max(...used)-Math.min(...used)+1},(_,i)=>Math.min(...used)+i):[];if(!hours.length)return empty('Delivery completion times were not recorded.');return `<div class="heat-scroll"><div class="delivery-heatmap" style="grid-template-columns:44px repeat(${hours.length},minmax(32px,1fr))"><span></span>${hours.map(h=>`<span>${h%12||12}${h<12?'a':'p'}</span>`).join('')}${data.heat.map(d=>`<strong>${d.day}</strong>${hours.map(h=>{const n=d.hours[h],level=n?Math.max(1,Math.ceil(n/max*4)):0;return `<button class="heat-cell heat-${level}" type="button" ${note(`${d.day}, ${h%12||12} ${h<12?'AM':'PM'}: ${n} deliveries completed`)}>${n||'·'}</button>`;}).join('')}`).join('')}</div></div><p class="muted">Delivery completion time in Seattle. Darker cells mean more completed deliveries. These are observed orders, not staffing recommendations.</p>`;}
function timeline(data,selectedId,page){
 const shift=data.shifts.find(s=>s.id===selectedId)||data.shifts.at(-1);if(!shift)return card('Explore a shift','Choose a completed shift to see its recorded stages.',empty('No completed shifts in this date range.'),true);
 const rows=data.timings.filter(d=>d.shiftId===shift.id).sort((a,b)=>(stamp(a.enteredAt)??0)-(stamp(b.enteredAt)??0)),pages=Math.max(1,Math.ceil(rows.length/12)),current=Math.min(Math.max(0,page),pages-1),visible=rows.slice(current*12,current*12+12),stages=[{from:'enteredAt',to:'readyAt',key:'addedToReady',label:'Added → ready',color:PALE},{from:'readyAt',to:'departedAt',key:'readyToDeparture',label:'Ready → departure',color:BLUE},{from:'departedAt',to:'completedAt',key:'departureToDelivery',label:'Departure → delivery',color:GREEN}];
 const points=[shift.startedAt,shift.endedAt,...rows.flatMap(d=>[d.enteredAt,d.readyAt,d.departedAt,d.completedAt])].map(stamp).filter(v=>v!==null),min=Math.min(...points),max=Math.max(min+60000,...points),x=t=>100+(t-min)/(max-min)*460;
 let body=`<label for="timeline-shift">Completed shift</label><select id="timeline-shift">${[...data.shifts].reverse().map(s=>`<option value="${esc(s.id)}" ${s.id===shift.id?'selected':''}>${date(s.startedAt)} · ${time(s.startedAt)} – ${time(s.endedAt)}</option>`).join('')}</select>${legend(stages)}<p class="muted">Added → ready starts when you entered the ticket; it is not the full kitchen preparation time. Departure → delivery includes walking, loading, traffic and earlier batch stops.</p>`;
 if(visible.length){let svg=svgStart('Recorded order stages for this shift',50+visible.length*45);for(let i=0;i<=4;i++){const t=min+(max-min)*i/4;svg+=`<line x1="${x(t)}" x2="${x(t)}" y1="25" y2="${30+visible.length*45}" class="chart-gridline"/><text x="${x(t)}" y="16" text-anchor="middle" class="chart-axis">${esc(time(new Date(t).toISOString()))}</text>`;}
 visible.forEach((d,i)=>{const y=35+i*45,label=`Order ${current*12+i+1}`;svg+=`<text x="2" y="${y+14}" class="chart-axis">${current*12+i+1} · ${d.kind}</text>`;let has=false;for(const s of stages){if(d[s.key]===null)continue;has=true;const text=`${label} · ${s.label}: ${num(d[s.key])} min, ${time(d[s.from])} to ${time(d[s.to])}`;svg+=`<rect x="${x(stamp(d[s.from]))}" y="${y}" width="${Math.max(2,x(stamp(d[s.to]))-x(stamp(d[s.from])))}" height="21" rx="3" fill="${s.color}" ${note(text)}><title>${esc(text)}</title></rect>`;}if(!has)svg+=`<text x="105" y="${y+14}" class="chart-axis">Stage durations not recorded</text>`;});body+=`<p class="muted timeline-swipe">Swipe sideways to explore the full timeline.</p><div class="timeline-scroll">${svg}</svg></div>${table(['Order','Added','Ready','Departure','Delivered'],visible.map((d,i)=>[current*12+i+1,time(d.enteredAt),time(d.readyAt),time(d.departedAt),time(d.completedAt)]))}<div class="pagination"><button data-timeline-page="-1" ${current===0?'disabled':''}>← Previous orders</button><span>${current*12+1}–${Math.min(rows.length,(current+1)*12)} of ${rows.length}</span><button data-timeline-page="1" ${current===pages-1?'disabled':''}>Next orders →</button></div>`;}else body+=empty('No completed deliveries recorded for this shift.');
 const tasks=taskLeaves().filter(t=>shift.tasks?.[t.key]);if(shift.tasks?.special?.trim())tasks.push({key:'special',label:shift.tasks.special});body+=`<h4>Kitchen work this shift</h4>${tasks.length?`<ul class="timeline-tasks">${tasks.map(t=>`<li><strong>${esc(t.label)}</strong><span>${time(shift.taskCompletedAt?.[t.key])}</span></li>`).join('')}</ul>`:'<p class="muted">No kitchen task check-offs recorded.</p>'}<p class="muted">A missing stage or task time is shown as “Not recorded.” Existing records are never backfilled with invented times.</p>`;
 return card('Explore a shift','Select a shift, then tap a bar or view its data. Timeline times use Seattle time.',body,true);
}
export function visualReports(state,shifts,{selectedShift=null,timelinePage=0}={}){
 const data=reportData(state,shifts);if(!data.shifts.length)return `<section class="card"><h2>Your visual shift journal</h2>${empty('No completed shifts in this date range. End a shift or choose another period to see charts.')}<p class="muted">Active shifts are not included. Sample mode lets you explore the charts without changing real records.</p></section>`;
 const volume=volumeBuckets(data.perShift),vol=volume.items.map(i=>({...i,label:i.key,short:i.key.slice(5),value:i.deliveries})),kindSummary=['single','batch'].map(k=>{const rows=data.timings.filter(d=>d.kind===k),known=rows.filter(d=>d.departureToDelivery!==null),wait=rows.filter(d=>d.readyToDeparture!==null);const mid=xs=>{const s=xs.sort((a,b)=>a-b);return s.length?(s[Math.floor(s.length/2)]+s[Math.ceil(s.length/2)-1])/2:null;};return {label:k==='single'?'Single orders':'Orders in batches',out:mid(known.map(d=>d.departureToDelivery)),wait:mid(wait.map(d=>d.readyToDeparture)),n:known.length,waitN:wait.length};}),scheduled=[...data.knownScheduled].sort((a,b)=>stamp(a.completedAt)-stamp(b.completedAt)).slice(-20).map((d,i)=>({label:`${i+1}. ${date(d.scheduledAt)} · ${time(d.scheduledAt)}`,short:String(i+1),value:d.scheduledDelta}));
 return `<section class="visual-report-intro"><div><div class="eyebrow">YOUR PRIVATE SHIFT JOURNAL</div><h2>The shape of your shifts.</h2><p>${data.shifts.length} completed shifts · ${data.deliveries.length} completed deliveries. ${data.shifts.length<5?'Early records: these charts describe what you have logged so far; they do not establish a trend.':'Explore patterns in the selected records. Different routes, order volume and kitchen work affect the numbers.'}</p></div><button class="outline" data-action="print-reports">Print / save PDF</button></section><nav class="report-jumps" aria-label="Chart sections"><a href="#report-overview">Overview</a><a href="#report-timing">Timing</a><a href="#report-patterns">Patterns</a><a href="#report-tasks">Tasks</a><a href="#report-timeline">Shift timeline</a></nav><div class="report-coverage"><strong>What’s recorded</strong><span>Departure → delivery: ${data.durationCount} / ${data.deliveries.length}</span><span>Ready → departure: ${data.readyCount} / ${data.deliveries.length}</span><span>Scheduled timing: ${data.knownScheduled.length} / ${data.scheduled.length}</span><small>Missing or reversed timestamps are unavailable, never zero. No speed targets or performance scores.</small></div><p class="chart-selection" id="chart-selection" role="status" aria-live="polite">Tap a chart bar, point or heatmap cell for its value. Every graph also has text or a data table.</p><h2 class="report-section-title" id="report-overview">At a glance</h2><div class="chart-grid">${card('Completed deliveries',`Grouped by ${volume.mode}; only recorded shifts are shown.`,bars('Completed deliveries over time',vol,[{key:'value',label:'Deliveries',color:GREEN}]))}${card('Single & batch trips','A batch has multiple delivery stops. This is a workload mix, not a score.',donut(data))}${card('Actual miles by shift','Odometer mileage includes the return to the restaurant. Missing shift dates are not zero-mile shifts.',line('Actual miles by shift',data.perShift,'miles','Actual miles',BLUE,'mi'))}${card('Miles per completed delivery','Whole-shift mileage divided by completed deliveries; distance is not allocated to individual orders.',line('Miles per completed delivery',data.perShift,'milesPerDelivery','Miles per delivery',GOLD,'mi'))}</div><h2 class="report-section-title" id="report-timing">Delivery timing</h2><div class="timing-highlights"><div><strong>${data.tripMedian===null?'—':num(data.tripMedian)+' min'}</strong><span>Median departure → delivery · ${data.durationCount} orders</span></div><div><strong>${data.waitMedian===null?'—':num(data.waitMedian)+' min'}</strong><span>Median ready → departure · ${data.readyCount} orders</span></div><div><strong>${data.knownScheduled.length?data.onTime+' / '+data.knownScheduled.length:'—'}</strong><span>At or before requested arrival · no grace period assumed</span></div></div><div class="chart-grid">${card('Departure → delivery by shift','Median per shift. Batch orders include time spent visiting earlier stops; this is not pure driving time.',line('Median departure to delivery by shift',data.perShift,'tripMinutes','Median departure to delivery',GREEN,'min'))}${card('Ready → departure by shift','Median per shift. Readiness timestamps begin with v0.7.1; older gaps remain visible.',line('Median ready to departure by shift',data.perShift,'waitMinutes','Median ready to departure',BLUE,'min'))}${card('Single vs. batch order timing','Separate medians, not a combined journey duration. Batch times include earlier delivery stops.',bars('Median order timing by trip type',kindSummary,[{key:'wait',label:'Ready → departure',color:BLUE},{key:'out',label:'Departure → delivery',color:GREEN}],v=>num(v)+' min',false,true)+`<p class="muted">${kindSummary.map(k=>`${k.label}: ${k.n} departure timings, ${k.waitN} readiness timings`).join(' · ')}</p>`)}${card('Time from departure to delivery','Each completed order with usable timestamps appears in one bucket. Batch stops take place on a shared trip.',bars('Distribution of departure to delivery times',data.buckets))}${card('Scheduled arrival: minutes early or late',`${scheduled.length} most recent timed scheduled orders shown; totals cover all selected shifts.`,bars('Minutes early or late for scheduled orders',scheduled,[{key:'value',label:'Minutes from requested time',color:GREEN}],v=>`${v>0?'+':''}${num(v)} min`,true)+`<p class="muted">${data.early} early · ${data.exact} exactly on time · ${data.late} late · ${data.scheduled.length-data.knownScheduled.length} not recorded. Numbers on the chart identify rows in its data table.</p>`,true)}</div><h2 class="report-section-title" id="report-patterns">When deliveries happen</h2><div class="chart-grid">${card('Completed deliveries by weekday & hour','Seattle time, across all selected completed shifts.',heatmap(data),true)}${card('Trips over time',`Single and batch trip counts grouped by ${volume.mode}.`,bars('Single and batch trip counts over time',vol))}${card('Kitchen contributions by shift','Recorded task selections, including special tasks. Counts are check-offs, not workload or quantity estimates.',line('Task check-offs by shift',data.perShift,'tasks','Tasks checked off',PALE,'tasks'))}</div><h2 class="report-section-title" id="report-tasks">Kitchen work, made visible</h2><div class="chart-grid">${card('Tasks completed','Each bar shows how many selected shifts include that completed task.',taskBars(data),true)}</div><h2 class="report-section-title" id="report-timeline">A closer look</h2><div class="chart-grid">${timeline(data,selectedShift,timelinePage)}</div><p class="muted report-private-note">These charts stay on this device. Mike’s end-of-shift message is unchanged. Print or export only when you choose to share.</p>`;
}
